def payments_from_amount_paid(apps, schema_editor):
    """Each invoice that was already (partly) paid gets one Payment for that amount,
    dated with its last payment date. Totals on the invoice stay exactly the same."""
    Expense = apps.get_model("core", "Expense")
    Payment = apps.get_model("core", "Payment")
    for exp in Expense.objects.filter(amount_paid__gt=0):
        Payment.objects.create(
            expense=exp, date=exp.paid_date or exp.date, amount=exp.amount_paid,
            reference="Recorded before payment history",
        )


